import{_ as t,a as o,b as r,c as a,d as n,e as s,f as i}from"./chunks/frames-viewer.OHjJ4sTJ.js";import{_ as l,o as g,c as h,a2 as m}from"./chunks/framework.Bzj1XTnB.js";const y=JSON.parse('{"title":"Frames, onion skin and the timeline","description":"Add and arrange frames, hold drawings longer, see neighbouring frames, make loops and play your animation.","frontmatter":{"lang":"en","slug":"frames-and-timeline","order":5,"title":"Frames, onion skin and the timeline","description":"Add and arrange frames, hold drawings longer, see neighbouring frames, make loops and play your animation."},"headers":[],"relativePath":"frames-and-timeline.md","filePath":"frames-and-timeline.md"}'),p={name:"frames-and-timeline.md"};function d(f,e,c,u,b,k){return g(),h("div",null,[...e[0]||(e[0]=[m('<h1 id="frames-onion-skin-and-the-timeline" tabindex="-1">Frames, onion skin and the timeline <a class="header-anchor" href="#frames-onion-skin-and-the-timeline" aria-label="Permalink to &quot;Frames, onion skin and the timeline&quot;">​</a></h1><p>An animation is a row of frames. Each frame is one drawing; played quickly one after another, they move.</p><h2 id="the-frame-strip" tabindex="-1">The frame strip <a class="header-anchor" href="#the-frame-strip" aria-label="Permalink to &quot;The frame strip&quot;">​</a></h2><p>The thumbnails above the bottom bar are your frames. The current one is in the middle with a pink border.</p><ul><li><strong>Tap</strong> a frame to go to it.</li><li><strong>Drag the strip</strong> (or the pink handle above it) to scrub through the animation. A readout shows the current frame, the total and the seconds.</li><li><strong>Pink +</strong> — adds a new, empty frame after the current one.</li><li><strong>▶</strong> plays the animation, <strong>⏮ / ⏭</strong> jump to the first and last frame. Tap the screen to stop.</li></ul><h2 id="frame-actions" tabindex="-1">Frame actions <a class="header-anchor" href="#frame-actions" aria-label="Permalink to &quot;Frame actions&quot;">​</a></h2><p><strong>Long-press a frame</strong> to open its actions.</p><p><img src="'+t+'" alt="Frame actions"></p><ul><li><strong>Hold</strong> − / + — show this drawing for longer (up to 48 frames) without drawing it again.</li><li><strong>Duplicate</strong>, <strong>Delete</strong>, <strong>Copy</strong>, <strong>Paste before</strong>, <strong>Paste after</strong>, <strong>Move left</strong>, <strong>Move right</strong>, <strong>Share</strong> (as a picture).</li><li>Tap <strong>Done</strong>, or anywhere outside the bar, to close it.</li></ul><h2 id="onion-skin" tabindex="-1">Onion skin <a class="header-anchor" href="#onion-skin" aria-label="Permalink to &quot;Onion skin&quot;">​</a></h2><p>Onion skin shows faint copies of the frames before and after, so you can line up your next drawing. It is on for new projects and never shows in your movie.</p><p><img src="'+o+'" alt="Onion skin on the canvas"></p><p>Change it in <strong>⋮ → Onion skin → Edit</strong>:</p><p><img src="'+r+'" alt="Onion skin settings"></p><ul><li><strong>Colored</strong> — earlier frames red, later frames green.</li><li><strong>Looping</strong> — the last frame also shows the first, for animations that loop.</li><li><strong>Frames before / after</strong> — how many neighbours to show (0–10).</li><li><strong>Transparency before / after</strong> and <strong>Skip frames</strong>.</li></ul><h2 id="grid" tabindex="-1">Grid <a class="header-anchor" href="#grid" aria-label="Permalink to &quot;Grid&quot;">​</a></h2><p><strong>⋮ → Grid</strong> draws guide lines over the canvas to help with spacing. <strong>Edit</strong> sets the line spacing and how strong they are. The grid is never in your movie.</p><h2 id="the-full-timeline" tabindex="-1">The full timeline <a class="header-anchor" href="#the-full-timeline" aria-label="Permalink to &quot;The full timeline&quot;">​</a></h2><p>Tap <strong>TIMELINE</strong> at the top for a bigger view of every frame, drawn to scale, with your layers and audio.</p><p><img src="'+a+'" alt="The timeline"></p><ul><li><strong>Tap</strong> a frame to go to it.</li><li><strong>Drag the pink grip</strong> on the edge of the current frame to hold it longer or shorter.</li><li><strong>Long-press</strong> a frame to select it; keep dragging to move it. Tap more to select several.</li><li><strong>Pinch</strong> to zoom the timeline.</li><li>The <strong>Hold</strong> card at the bottom left changes the selected frame&#39;s hold; the preview on the right plays the animation.</li></ul><p><img src="'+n+'" alt="Several frames selected"></p><h3 id="groups-and-loops" tabindex="-1">Groups and loops <a class="header-anchor" href="#groups-and-loops" aria-label="Permalink to &quot;Groups and loops&quot;">​</a></h3><p>Select some frames and tap <strong>Group</strong>. The group can now be repeated with <strong>Loop</strong> — great for a walk cycle or a blinking eye that plays several times. <strong>Ungroup</strong> undoes it and <strong>Split</strong> cuts a group in two.</p><p><img src="'+s+'" alt="A frame group with a loop"></p><p>The bar at the bottom also has <strong>Undo</strong>, <strong>Redo</strong>, <strong>Select / Deselect</strong>, <strong>Duplicate</strong>, <strong>Copy</strong>, <strong>Paste</strong>, <strong>Delete</strong> and <strong>Layer</strong>. Tap <strong>TIMELINE</strong> again (or ✕ on the preview) to close it.</p><h2 id="all-frames-at-once" tabindex="-1">All frames at once <a class="header-anchor" href="#all-frames-at-once" aria-label="Permalink to &quot;All frames at once&quot;">​</a></h2><p><strong>⋮ → Frames</strong> shows every frame in a grid. Tap one to open it, long-press to select (then duplicate, delete, copy, paste or share), or long-press and drag to move.</p><p><img src="'+i+'" alt="Frames viewer"></p><h2 id="speed-and-timing" tabindex="-1">Speed and timing <a class="header-anchor" href="#speed-and-timing" aria-label="Permalink to &quot;Speed and timing&quot;">​</a></h2><ul><li><strong>Frames per second</strong> (Project settings) sets the speed of the whole animation. 12 fps is a good start; 24 fps looks like film; 4–8 fps looks choppy on purpose.</li><li><strong>Timing</strong> — <em>On twos</em> holds every drawing for two frames, so you draw half as many for the same length. Hold single frames from the frame actions or the timeline.</li></ul>',31)])])}const T=l(p,[["render",d]]);export{y as __pageData,T as default};
